;// ./src/data/cases.json
const cases_namespaceObject = /*#__PURE__*/JSON.parse('[{"id":"case-01","url":"case-01","title":"KAWS × Dior — Dior Men SS19 (дебютный показ и кампания Кима Джонса), 2018","artists":["KAWS (Брайан Доннелли)"],"quotes":[{"artist":"KAWS (Брайан Доннелли)","text":"Нет, это просто разные люди, всё зависит от конкретного случая. Всё действительно зависит от проекта и людей. Точно так же крупные компании могут быть такими же лёгкими, если не легче, чем коллаборация с маленьким бутиком. С Dior всё было действительно просто, потому что я работал с Кимом Джонсом, а мы с ним довольно дружелюбны. Это было весело. Мы просто спрашивали, как мы можем это сделать, и сделали всё в жёсткие сроки."}]},{"id":"case-02","url":"case-02","title":"Daniel Arsham × Dior — Dior Men SS20 (сет-дизайн и объекты), 2019","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Мы провели много времени в архиве Dior, рассматривая дизайны и объекты, созданные либо самим господином Диором, либо в доме, начиная, по сути, с 50-х. […] И переосмысливая эти объекты как археологические реликвии; думайте о них как о вещах, которые могли бы быть найдены через тысячу, десять тысяч лет. В этих объектах происходит материальный сдвиг: я воссоздал их в разных видах кристалла — кварце, селените, синем и розовом кальците."},{"artist":"Daniel Arsham","text":"Эти бренды — иконы определённого момента времени, и во всей своей работе, если вернуться назад, я всегда выбирал, знаете, камеру Leica, кроссовки Jordan или баскетбольный мяч Spalding и переделывал эти вещи в таких геологических материалах. Выбор самого объекта в некотором смысле так же важен, как и визуальное качество работы."}]},{"id":"case-03","url":"case-03","title":"Hajime Sorayama × Dior — Dior Men Pre-Fall 2019, Токио, 2018","artists":["Hajime Sorayama"],"quotes":[{"artist":"Hajime Sorayama","text":"Я описываю свою коллаборацию с Кимом как двух чудаков, которые веселятся. У Кима великолепное художественное видение. Как креативный человек, я видел это с самого начала."}]},{"id":"case-04","url":"case-04","title":"GucciGhost (Trevor Andrew) × Gucci — коллекция Gucci Fall 2016 / «GucciGhost», 2016","artists":["GucciGhost (Trevor Andrew)"],"quotes":[{"artist":"Trevor Andrew (GucciGhost)","text":"Я коллекционировал Gucci и вещи, вдохновлённые Gucci, 15 лет. На меня всегда влияли streetwear-бренды с обилием логотипов. Gucci не был streetwear-брендом, но моя любовь к логотипам сделала его богом всех брендов для меня. Я был одержим их монограммой и логотипом и тем, что это казалось мне совершенно не по средствам. Это было больше чем просто бренд; для меня это был язык. Gucci означал «величие»."},{"artist":"Trevor Andrew","text":"Я взял идеальный логотип и низвёл его до сырой, весёлой, несовершенной вещи. Нужен был просто подходящий человек, чтобы понять, что я делаю."},{"artist":"Trevor Andrew","text":"Алессандро рискует, я рискую. Он действительно дал мне свободу творить и чувствовать себя комфортно. […] Я не могу дождаться, когда эти вещи выйдут. Это подтверждение моей сумасшедшинки."}]},{"id":"case-05","url":"case-05","title":"Takashi Murakami × Louis Vuitton — Louis Vuitton × Murakami (2003; ре-эдишн 2025)","artists":["Takashi Murakami"],"quotes":[{"artist":"Takashi Murakami","text":"В Louis Vuitton, с Марком Джейкобсом, мы общались по электронной почте: я отправил Марку 70 или 80 изображений, и он выбрал одно или два… но на этот раз Vans согласились на всё!"},{"artist":"Takashi Murakami","text":"Время всего этого действительно сложилось в мою пользу, так что в конечном счёте я чувствую, что мне повезло."}]},{"id":"case-06","url":"case-06","title":"Yayoi Kusama × Louis Vuitton — «Creating Infinity», 2023","artists":["Yayoi Kusama"],"quotes":[],"note":"Прямых высказываний художницы о коллаборации 2023 в отчёте не обнаружено."},{"id":"case-07","url":"case-07","title":"Daniel Arsham × RIMOWA — «Eroded Attaché» (2019) и «Eroded Turntable in Pilot Case» (2022)","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Мы с RIMOWA разделяем интерес к процессу, к эволюции объекта во времени. Чемодан покрывается наклейками или следами; скульптура разрушается эрозией и кристаллизуется."},{"artist":"Daniel Arsham","text":"Многие мои работы опираются на определённый уровень несовершенства, и с Rimowa это определённо не так. Там всё дело в точности, так что возможность работать в таких условиях была интересной."}]},{"id":"case-08","url":"case-08","title":"Daniel Arsham × Tiffany & Co. — «Bronze Eroded Tiffany Blue Box», 2021","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Меня всегда притягивают предметы, которые сразу культурно узнаваемы. У коробки Tiffany Blue Box® есть эта сила. Я хотел подойти к ней иначе, чем было задумано изначально, придав ей потрёпанное, состаренное качество, которое представляет её историю, то, насколько она является неотъемлемой частью нашего мира сегодня, и то, как она будет оставаться актуальной десятилетия, даже века спустя."},{"artist":"Daniel Arsham","text":"Tiffany Blue настолько узнаваем, но я хотел использовать его иначе, чем было задумано изначально. Моя работа представляет современный объект так, как если бы мы перенесли его в будущее и вернули обратно. И это смещение во времени создаёт своего рода парадокс в самом объекте. У вас есть вещь, которую вы знаете из своей текущей эпохи, но она выглядит старой."}]},{"id":"case-09","url":"case-09","title":"KAWS × UNIQLO (UT) — капсула UT SS2016, 2016","artists":["KAWS (Брайан Доннелли)"],"quotes":[{"artist":"KAWS (Брайан Доннелли)","text":"Мне всегда нравилось работать в разных медиумах — будь то пластиковые игрушки, живопись, бронзовая скульптура или графический дизайн. UT — это классный холст, чтобы сделать мои работы доступными людям практически везде. Мне понравилось работать с командой Uniqlo, чей энтузиазм беспримерен. Здорово быть частью удивительной платформы UT моего друга и коллеги-художника NIGO."}]},{"id":"case-10","url":"case-10","title":"Tom Sachs × Nike (NikeCraft) — Mars Yard (2012), General Purpose Shoe (2022), Mars Yard 3.0 (2025)","artists":["Tom Sachs"],"quotes":[{"artist":"Tom Sachs","text":"Из ресурсов вокруг нас мы можем создавать свои собственные миры."},{"artist":"Tom Sachs","text":"Бриколаж — это слово, которое используют художники, но это больше чем способ создания скульптуры, это действительно образ жизни."},{"artist":"Tom Sachs","text":"Кроссовки могут делать то, чего не могут другие формы искусства. Я могу делать скульптуры-бриколажи всю свою карьеру, но больше людей научатся понимать, что такое бриколаж и почему он важен, благодаря кроссовкам, чем благодаря всем остальным моим работам вместе взятым."},{"artist":"Tom Sachs","text":"Ценности NikeCraft не изменились, но они оттачивались на протяжении последних 20 лет. С самого начала я рассматривал NikeCraft как художественный проект: место, где результаты и идеи моей студии могли бы достичь более широкой аудитории через скульптуру, известную как кроссовок. Эти два десятилетия — ещё одно напоминание о том, что искусство во всём, и оно демонстрируется через Mars Yard в высшей художественной галерее — на улицах."},{"artist":"Tom Sachs","text":"Mars Yard всегда было трудно достать, и их всегда будет трудно достать. Если вы хотите их, вам придётся за них поработать."},{"artist":"Tom Sachs","text":"Я [начал работать] с Nike, потому что устал от элитизма искусства; искусство действительно дорогое. Я такой: «Нет, я просто сделаю кроссовки с Nike, и все поймут»."}]},{"id":"case-11","url":"case-11","title":"Samuel Ross (A-COLD-WALL*) × Nike — капсула Nike x A–COLD–WALL*, 2018","artists":["Samuel Ross (A-COLD-WALL*)"],"quotes":[{"artist":"Samuel Ross","text":"С Vomero появилась возможность действительно возвысить технологию своего времени и модернизировать эстетику, которая не идёт на компромисс со своим назначением и функцией. Интересно смотреть на кроссовок, у которого такой красивый и отточенный каркас, а затем иметь возможность выделить отдельные аспекты этого кроссовка, чтобы действительно возвысить технологию. Очень захватывающе взять что-то очень красивое и не обязательно переосмыслить, а переоценить продукт."},{"artist":"Samuel Ross","text":"В одежде, которую мы производим с Nike, есть элемент утончённости, вплетённый в простые формы, которые имеют эти небольшие детали. Эти детали сводятся к использованию таких вещей, как японский нейлон в парке, который изначально грубый, но при носке действительно становится мягче."},{"artist":"Samuel Ross","text":"Вот почему A-COLD-WALL* сработал: потому что действительно не было преимущественно чёрного британского fashion-нарратива, который говорит с рабочим классом и может общаться с художественным миром моего поколения…"}]},{"id":"case-12","url":"case-12","title":"Samuel Ross × Oakley — «Oakley by Samuel Ross» (FW18, Season 2 — 2019, Season 3)","artists":["Samuel Ross (A-COLD-WALL*)"],"quotes":[{"artist":"Samuel Ross","text":"Это была игра для думающего человека — соединить мой усердный подход с любовью и фокусом Oakley на технической одежде для активного отдыха. Мы позаботились о том, чтобы технологии Oakley были использованы через конкретные стили и фурнитуру."},{"artist":"Samuel Ross","text":"Во втором сезоне моя главная цель была естественно развить широту моей коллаборации с Oakley. По мере роста партнёрства наше общее представление о современном герое outdoors становится более определённым — выражение, слитое с функцией."},{"artist":"Samuel Ross","text":"Это возникло благодаря восхищению с обеих сторон. У Oakley более техническая, более эмоциональная форма выражения, которую он способен воплощать в одежде. […] Это как счастливая случайность."},{"artist":"Samuel Ross","text":"Думаю, главное различие — в рассказывании истории. Там совершенно другой нарратив. Так что хотя материалы согласованы и есть нюансы эстетики ACW*, которые путешествуют со мной и тем, что я делаю, главная цель с Oakley — создавать техническую одежду для outdoors."}]},{"id":"case-13","url":"case-13","title":"Futura (Leonard McGurr) × Hennessy — лимитированная бутылка Hennessy V.S, 2012","artists":["Futura (Leonard McGurr)"],"quotes":[{"artist":"Futura","text":"Для меня честь создавать дизайн для такого бренда, как Hennessy, из-за их сильной связи с искусством и поддержки искусства. Работая в этом новом медиуме, я смог бросить себе вызов, пойти на шаг дальше и достучаться до любителей стрит-арта через революционный новый дизайн."}]},{"id":"case-14","url":"case-14","title":"Futura × Off-White™ × Nike — Nike Dunk Low «Virgil Abloh™ x Futura Laboratories» (показ SS20; аукцион Sotheby\'s 2023)","artists":["Futura (Leonard McGurr)"],"quotes":[{"artist":"Futura","text":"Удивительно наконец увидеть, как \'Virgil Abloh x Futura Laboratories\' выходят таким образом. Я надеюсь почтить мою дружбу с Вирджилом и нашу творческую совместную работу. Спасибо SOTHEBY\'s за проведение этого благотворительного события. И самое главное, спасибо ШЭННОН за продвижение этого проекта. ВИРДЖИЛ НАВСЕГДА!!"}]},{"id":"case-15","url":"case-15","title":"Cindy Sherman × Supreme — скейтборды «Grotesque Series», 2017","artists":["Cindy Sherman"],"quotes":[],"note":"Прямых высказываний художницы о коллаборации в отчёте не обнаружено."},{"id":"case-16","url":"case-16","title":"KAWS × The North Face — коллекция «XX KAWS», 2022","artists":["KAWS (Брайан Доннелли)"],"quotes":[],"note":"Цитаты из пресс-релиза The North Face и самого KAWS в отчёте не извлечены."},{"id":"case-17","url":"case-17","title":"KAWS × Epic Games (Fortnite) × Serpentine — выставка «NEW FICTION», 2022","artists":["KAWS (Брайан Доннелли)"],"quotes":[{"artist":"KAWS","text":"Это невероятно захватывающий проект для меня. Мне всегда нравится исследовать новые медиумы для своего искусства. Коллаборация с Fortnite означает, что всё соединяется в сложной выставке, которая происходит в параллельных реальностях."},{"artist":"KAWS","text":"Это настоящая выставка 1:1, в классическом музейном пространстве, где картины и скульптуры висят и расположены определённым образом, и именно так это было сделано в Fortnite. Для многих подростков это может быть первый раз на музейной художественной выставке, и я думаю, есть отличная возможность предоставить это в среде — Fortnite, — которая им так знакома. Я помню, когда был младше, галереи казались мне пугающими, но здесь это на вашей территории. И захватывающе, что этого никогда раньше не делали."}]},{"id":"case-18","url":"case-18","title":"KAWS × Acute Art — «EXPANDED HOLIDAY» (AR), 2020","artists":["KAWS (Брайан Доннелли)"],"quotes":[{"artist":"KAWS","text":"Когда я осознал качество, которого можно достичь и которое можно испытать в AR, меня сразу привлекла его потенциальность. Я всю карьеру создаю объекты и выставляю работы в публичных пространствах, и это позволяет мне расширить это на совершенно новую арену. Возможности локаций и масштаба бесконечны, и я рад начать новый диалог в этом медиуме."}]},{"id":"case-19","url":"case-19","title":"Daniel Arsham × Pokémon — «Daniel Arsham × Pokémon» / «A Ripple in Time», 2020","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Вымышленная археология — это действительно идея взять все объекты из нашего сегодняшнего дня и представить, как если бы мы были археологами в будущем и смотрели на эти объекты из нашей повседневной жизни или повседневного опыта. Думаю, есть что-то плодовитое и воздействующее в попытке выйти за пределы собственных временных рамок. Это даёт нам перспективу наших собственных переживаний и жизней. Через эти работы я надеюсь изменить понимание людьми времени в целом."},{"artist":"Daniel Arsham","text":"Идея вымышленной археологии состоит в том, чтобы брать объекты из настоящего и переформировывать их в геологических материалах, проецируя их в будущее. Это как если бы вы могли отправиться в будущее и посмотреть на остатки своей собственной жизни, своей собственной цивилизации, действительно."}]},{"id":"case-20","url":"case-20","title":"Daniel Arsham × Hot Wheels (Mattel Creations) — 2023–2024","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Mattel Creations разработала творческие способы воплотить моё видение, мысля нестандартно и экспериментируя с новыми материалами и процессами. Это первый раз, когда Silkstone использован на модели Hot Wheels, и первый раз, когда я работаю с этим материалом, что делает это историческим моментом для нас обоих."},{"artist":"Daniel Arsham","text":"Партнёрство с Hot Wheels дало мне возможность создать вещи, которые воплощают идеальную синергию ностальгии и инновации. Включение личных фаворитов, таких как Porsche 930, отдаёт дань моей истории и при этом соответствует сути нашей коллаборации."}]},{"id":"case-21","url":"case-21","title":"Daniel Arsham × Porsche — «NEBULA 928», 2023","artists":["Daniel Arsham"],"quotes":[{"artist":"Daniel Arsham","text":"Он не так популярен во вселенной Porsche."}]},{"id":"case-22","url":"case-22","title":"Julie Mehretu × BMW — BMW Art Car #20, 2024","artists":["Julie Mehretu"],"quotes":[{"artist":"Julie Mehretu","text":"Весь проект BMW Art Car — о изобретении, о воображении, о раздвигании пределов возможного. Я не думаю об этой машине как о чём-то, что вы стали бы выставлять. Я думаю о ней как о чём-то, что будет участвовать в гонке в Ле-Мане. Это перформативная живопись. Моя BMW Art Car была создана в тесной коллаборации с командами автоспорта и инженерии. BMW Art Car завершается только тогда, когда гонка окончена."},{"artist":"Julie Mehretu","text":"В студии, где у меня была модель BMW M Hybrid V8, я просто сидела перед картиной и думала: что произойдёт, если эта машина как будто пройдёт сквозь эту картину и окажется под её воздействием. Идея была сделать ремикс, мэшап картины. Я продолжала видеть, как эта картина словно стекает в машину. Даже «ноздри» машины вдохнули картину."}]},{"id":"case-23","url":"case-23","title":"Jeff Koons × BMW — BMW Art Car #17 (M3 GT2), 2010","artists":["Jeff Koons"],"quotes":[{"artist":"Jeff Koons","text":"Эти гоночные машины подобны жизни: они мощные, и в них много энергии. Вы можете участвовать в этом, дополнять это и позволять себе возвышаться вместе с её энергией. Под капотом много мощности, и я хочу дать своим идеям возвыситься вместе с машиной — это действительно соединение с этой мощью."},{"artist":"Jeff Koons","text":"Эта гонка была очень бодрящим опытом. Удивительно видеть самоотдачу всех вовлечённых людей. Болельщики спят в палатках и не спят гораздо больше 24 часов, чтобы отпраздновать это событие. Это действительно меня заводит, поскольку я понимаю, что для всех людей быть здесь — нечто по-настоящему особенное."}]},{"id":"case-24","url":"case-24","title":"John Baldessari × BMW — BMW Art Car #19 (M6 GTLM), 2016","artists":["John Baldessari"],"quotes":[{"artist":"John Baldessari","text":"До этого в моей жизни была только одна работа, связанная с машиной, и это было изображение машины. Так что для проекта BMW Art Car я вошёл на неизведанную территорию — не только с точки зрения сюжета, но и переходя от двухмерного искусства к трёхмерному. Вызов, который мне понравился! Идеи пришли все сразу: например, красная точка на крыше, чтобы её было видно сверху, FAST с одной стороны и изображение машины с другой. Мне нравится эта двусмысленность — иметь двухмерность и трёхмерность одновременно. Рассматривая машину как икону современной жизни, моя концепция получилась игриво-сатирической, но она также подчёркивает некоторые фирменные идеи, которые я использую. Так что можно сказать, BMW Art Car — это определённо типичный Бальдессари и самое быстрое произведение искусства, которое я когда-либо создавал!"}]},{"id":"case-25","url":"case-25","title":"Andy Warhol × BMW — BMW Art Car #4 (M1), 1979","artists":["Andy Warhol"],"quotes":[{"artist":"Andy Warhol","text":"Я попытался передать ощущение скорости. Когда машина едет очень быстро, все линии и цвета становятся размытыми."},{"artist":"Andy Warhol","text":"Я обожаю эту машину, она гораздо лучше произведения искусства."}]},{"id":"case-26","url":"case-26","title":"Andy Warhol × Absolut — «Absolut Warhol», 1985","artists":["Andy Warhol"],"quotes":[],"note":"Прямой цитаты Уорхола об Absolut в отчёте не обнаружено."},{"id":"case-27","url":"case-27","title":"Keith Haring × Absolut — литографии 1986 / «Absolut Haring Artist Edition», 2025","artists":["Keith Haring"],"quotes":[],"note":"Прямых высказываний Харинга об Absolut в отчёте не обнаружено."},{"id":"case-28","url":"case-28","title":"Estate of Jean-Michel Basquiat × Dom Pérignon — Vintage 2015 Special Edition «In Italian», 2024","artists":["Jean-Michel Basquiat"],"quotes":[],"note":"Прямые высказывания Баския о коллаборации невозможны; цитаты наследия в отчёте нет."},{"id":"case-29","url":"case-29","title":"A$AP Rocky (AWGE) × Mercedes-Benz — кампания «Grow Up» (2017) и коллекция AWGE × Mercedes-Benz × PacSun (2022)","artists":["A$AP Rocky (Раким Майерс)"],"quotes":[{"artist":"A$AP Rocky","text":"Я вырос в 90-х, так что это одна из самых важных эпох, из которых я черпаю вдохновение. Эта коллекция отдаёт дань всей ностальгии, которая возвращается ко мне каждый раз, когда я вижу эмблему Mercedes. […] PacSun казался естественным партнёром для продажи коллаборации."},{"artist":"A$AP Rocky","text":"Чувак, я не мог бы быть счастливее."}]},{"id":"case-30","url":"case-30","title":"A$AP Rocky × Ray-Ban — креативный директор; кампания «Blacked Out Icons» и Metal Collection (с Nas), 2025–2026","artists":["A$AP Rocky (Раким Майерс)","Nas"],"quotes":[{"artist":"Nas","text":"Чувак, мне сегодня вечером звонит Флако. Он хочет встретиться в Гарлеме. Забавно, это тот же ресторан, где я последний раз встречался с его отцом перед тем, как тот умер. Его отец был моим корешем."}],"note":"Прямых высказываний A$AP Rocky о коллаборации в отчёте не обнаружено."},{"id":"case-31","url":"case-31","title":"Hajime Sorayama × PUMA — капсула к Году Дракона, 2024","artists":["Hajime Sorayama"],"quotes":[{"artist":"Hajime Sorayama","text":"Чтобы сохранить мои творения для будущих поколений, пожалуйста, проявите добрую поддержку, покупая и нося эту коллаборацию!"},{"artist":"Hajime Sorayama","text":"Однажды ко мне во сне пришёл великий монах и сказал нарисовать дракона, чтобы истребить демонов, так что я изо всех сил постарался его нарисовать."},{"artist":"Hajime Sorayama","text":"Нет, не задумывался. За моти иди в магазин моти. В Японии есть такая поговорка. Эксперты знают лучше. Я просто рисую то, что мне нравится."}]},{"id":"case-32","url":"case-32","title":"Refik Anadol × Samsung — «Artificial Landscapes» для MICRO LED, 2021","artists":["Refik Anadol"],"quotes":[{"artist":"Refik Anadol","text":"Самое важное для меня — создать думающую кисть, кисть, которая может думать, которая может помнить и которая может мечтать."},{"artist":"Refik Anadol","text":"Есть коллаборация между машиной и человеком. С одними и теми же данными мы можем генерировать бесконечные версии одной и той же скульптуры, но выбор этого момента и создание этого момента во времени и пространстве — это и есть момент творения."}]}]');
